create or replace function public.get_owner_client_governance() returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; return jsonb_build_object('clients',coalesce((select jsonb_agg(x order by x.created_at desc) from (select c.id client_id,c.user_id,c.display_name,p.full_name,p.phone,p.account_status,c.verification_status,c.risk_level,c.risk_note,c.created_at,(select count(*) from public.properties pr where pr.client_id=c.id and pr.archived_at is null) property_count,(select count(*) from public.marketplace_jobs j where j.client_id=c.id) job_count,(select count(*) from public.marketplace_jobs j where j.client_id=c.id and j.status in ('open','accepted','assigned','active')) active_job_count,coalesce((select sum(coalesce(j.estimated_total_cents,0)) from public.marketplace_jobs j where j.client_id=c.id and j.status='completed'),0) lifetime_spend_cents,coalesce((select jsonb_agg(jsonb_build_object('id',pr.id,'name',pr.name,'address',pr.address)) from public.properties pr where pr.client_id=c.id and pr.archived_at is null),'[]'::jsonb) properties,coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'title',j.title,'status',j.status,'payment_status',j.payment_status,'estimated_total_cents',j.estimated_total_cents) order by j.created_at desc) from public.marketplace_jobs j where j.client_id=c.id),'[]'::jsonb) jobs from public.clients c join public.profiles p on p.id=c.user_id where p.role='client')x),'[]'::jsonb)); end $$;
create or replace function public.owner_set_client_account_status(p_client_id uuid,p_action text,p_reason text) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare c public.clients;s public.account_status;n integer;begin if public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED';end if;if nullif(btrim(p_reason),'') is null then raise exception 'REASON_REQUIRED';end if;if p_action not in('restore','restrict','suspend','terminate') then raise exception 'INVALID_CLIENT_ACTION';end if;select * into c from public.clients where id=p_client_id for update;if c.id is null then raise exception 'CLIENT_NOT_FOUND';end if;s:=case when p_action='restore' then 'approved'::public.account_status when p_action='terminate' then 'rejected'::public.account_status else 'disabled'::public.account_status end;update public.profiles set account_status=s,updated_at=now() where id=c.user_id;update public.clients set risk_level=case when p_action='restore' then 'low' when p_action='restrict' then 'medium' else 'high' end,risk_note=btrim(p_reason) where id=c.id;select count(*) into n from public.marketplace_jobs where client_id=c.id and status in('open','accepted','assigned','active');insert into public.owner_audit_log(actor_user_id,action,target_type,target_id,payload)values(auth.uid(),'client_account_'||p_action,'client',c.id,jsonb_build_object('reason',btrim(p_reason),'account_status',s,'active_jobs',n));return jsonb_build_object('client_id',c.id,'action',p_action,'account_status',s,'active_jobs',n);end $$;
revoke all on function public.get_owner_client_governance() from public;grant execute on function public.get_owner_client_governance() to authenticated;revoke all on function public.owner_set_client_account_status(uuid,text,text) from public;grant execute on function public.owner_set_client_account_status(uuid,text,text) to authenticated;
